-- User table schema
CREATE TABLE users (
    -- id: The user unique id
    id VARCHAR(64),
    -- domain: Domain associated with the user account
    domain VARCHAR(64),
    -- email: Email address of the user
    email VARCHAR(250),
    -- username: Username for the user account (required)
    username VARCHAR(64) NOT NULL,
    -- name: User's first name
    name VARCHAR(50),
    -- lastname: User's last name
    lastname VARCHAR(50),
    -- perms: List of permissions
    perms TEXT,
    -- enabled: If user is enabled
    enabled INTEGER,
    -- level: User level
    level INTEGER,
    -- password: User encrypted password
    password VARCHAR(64),
    token_version INTEGER,
    -- email_verified: Email verification status
    email_verified INTEGER,
    -- verified_at: Timestamp when email was verified
    verified_at INTEGER,
    -- id_role: Role assigned to the user, defines a default set of permissions
    id_role VARCHAR(64),
    -- two_factor_enabled: Flag T/F is 2FA is enabled
    two_factor_enabled INTEGER,
    -- two_factor_secret: The 2FA secret
    two_factor_secret VARCHAR(200),
    -- two_factor_recovery_codes: 2FA Recovery codes
    two_factor_recovery_codes TEXT,
    -- password_expired: Flag T/F: the password is expired and must be changed at the next login
    password_expired INTEGER,
    -- password_changed_at: Timestamp (unix ms) of the last password change. Null means unknown: the password never expires automatically
    password_changed_at INTEGER,
    -- password_max_age_days: Days after which this user must change the password. Null: use the global cfg.user.passwordMaxAgeDays. 0: never expires
    password_max_age_days INTEGER
);

-- Index on id: The user unique id
CREATE INDEX idx_users_id ON users(id);

-- Index on domain: Domain associated with the user account
CREATE INDEX idx_users_domain ON users(domain);

-- Index on email: Email address of the user
CREATE INDEX idx_users_email ON users(email);

-- Index on username: Username for the user account (required)
CREATE INDEX idx_users_username ON users(username);

-- Index on enabled: If user is enabled
CREATE INDEX idx_users_enabled ON users(enabled);

-- Index on level: User level
CREATE INDEX idx_users_level ON users(level);

-- Index on email_verified: Email verification status
CREATE INDEX idx_users_email_verified ON users(email_verified);

-- Index on id_role: Role assigned to the user, defines a default set of permissions
CREATE INDEX idx_users_id_role ON users(id_role);


