-- UserRefresh table schema
CREATE TABLE user_refresh_tokens (
    -- id: Refresh token record id
    id VARCHAR(64) PRIMARY KEY,
    -- id_user: Owning user id
    id_user VARCHAR(200) NOT NULL,
    -- token_hash: sha256 hex digest of the refresh token
    token_hash VARCHAR(200) NOT NULL,
    -- family_id: Rotation family: the chain of successors born from a single login
    family_id VARCHAR(200) NOT NULL,
    -- expires_at: Expiry, unix milliseconds
    expires_at INTEGER NOT NULL,
    -- used_at: Consumption timestamp, unix ms; non-null means already used
    used_at INTEGER,
    -- created: Creation timestamp, unix milliseconds
    created INTEGER NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Index on id_user: Owning user id
CREATE INDEX idx_user_refresh_tokens_id_user ON user_refresh_tokens(id_user);

-- Index on token_hash: sha256 hex digest of the refresh token
CREATE UNIQUE INDEX idx_user_refresh_tokens_token_hash ON user_refresh_tokens(token_hash);

-- Index on family_id: Rotation family: the chain of successors born from a single login
CREATE INDEX idx_user_refresh_tokens_family_id ON user_refresh_tokens(family_id);


